1* {
2    margin: 0;
3    padding: 0;
4    box-sizing: border-box;
5}
6
7body {
8    margin: 8px;
9    font-family: 'Helvetica', 'Arial', sans-serif;
10}
11
12h1 {
13    font-size: 40px;
14    color: #2a2a7b;
15    font-weight: bold;
16    margin: 20px;
17}
18
19div {
20    font-size: 24px;
