23}
24
25/* Game Screen Styles */
26#gameScreen {
27    display: none;
28    padding: 20px;
29    justify-content: space-around;
30}
31
32#turnInfo {
33    font-size: 28px;
34    font-weight: 500;
35    color: #6b6b9f;
36    margin-bottom: 40px;
37    text-align: center;
38}
39
40.game-board {
41    display: grid;
42    background: #40e7e7;
43    grid-template-columns: repeat(3, 1fr);
44    grid-template-rows: repeat(3, 100px);
45    grid-gap: 4px;
46    width: 320px;
47}
48
49.cell {
50    display: flex;
51    align-items: center;
52    justify-content: center;
53    background-color: white;
54    font-size: 36px;
55    font-weight: bold;
56    cursor: pointer;
57}
58
59.cell:hover {
60    background-color: #d5f7f7;
61}
62
63#player1Score, #player2Score {
64    padding: 18px 16px;
65    border-radius: 4px;
66    border: 2px solid #40e7e7;
67    text-align: center;
68    margin-bottom: 8px;
69}
70
71/* Setup Screen Styles */
72#setupScreen {
73    padding: 20px;
74    display: flex;
75    flex-direction: column;
76    align-items: center;
77}
78
79.input-group {
80    margin-bottom: 15px;
81    text-align: left;
82}
83
84.input-group label {
85    display: block;
86    color: #2a2a7b;
87    margin-bottom: 5px;
88}
89
90.input-group input {
91    width: 100%;
92    padding: 10px;
93    border: 1px solid #e0e0e0;
94    border-radius: 4px;
95    font-size: 16px;
96}
97
98#start-button {
99    width: 265px;
100    padding: 12px;
101    background-color: #0066ff;
102    color: white;
103    border: none;
104    border-radius: 4px;
105    font-size: 16px;
106    cursor: pointer;
107    margin-top: 20px;
108}

1// Check for player names input and update UI elements
2startGame.addEventListener('click', (event) => {
3    // Retrieve input values for player names or set default names
4    player1Name = document.querySelector(".player1-name").value || "Player 1";
5    player2Name = document.querySelector(".player2-name").value || "Player 2";
6
7    // Update the player name in the turn info
8    const turnInfoPlayerName = document.querySelector("#turnInfo .player1-name");
9    if (turnInfoPlayerName) {
10        turnInfoPlayerName.textContent = player1Name;
11    }
12
13    // Update the player names in the score panel
14    const player1ScorePanel = document.querySelector("#player1Score .player1-name");
15    if (player1ScorePanel) {
16        player1ScorePanel.textContent = player1Name;
17    }
18
19    const player2ScorePanel = document.querySelector("#player2Score .player2-name");
20    if (player2ScorePanel) {
21        player2ScorePanel.textContent = player2Name;
22    }
23
24    // Switch to the game screen
25    switchScreen();
26});
